const inc = $input.item.json;

// Gera as duas variantes do WhatsApp no formato salvo no mailing: com e sem o 9.
function fmt(telefone){
  let phone = String(telefone || '').replace(/\D/g, '');
  if (phone.startsWith('55')) phone = phone.slice(2);
  const ddd = phone.slice(0, 2);
  const numero = phone.slice(2);
  const com9 = numero.length === 8 ? '9' + numero : numero;
  const sem9 = (numero.length === 9 && numero.startsWith('9')) ? numero.slice(1) : numero;
  const f = (n) => n.length === 9
    ? `(${ddd}) ${n.slice(0,5)}-${n.slice(5)}`
    : `(${ddd}) ${n.slice(0,4)}-${n.slice(4)}`;
  return { com9: f(com9), sem9: f(sem9) };
}

const v = fmt(inc.telefone);
return { json: { inc, wpp_com9: v.com9, wpp_sem9: v.sem9 } };

const prep = $('Prepara Telefone e Inc').first().json;
const inc = prep.inc;

// Observacao que JA existe no banco (pode nao existir).
let obsAntiga = "";
try {
  const row = $('Busca Observação Atual').first().json;
  if (row && row.observacao != null) obsAntiga = String(row.observacao).trim();
} catch (e) { obsAntiga = ""; }

const body = { phone: inc.telefone };

// Campos cadastrais (entram como vierem, sem validacao).
const campos = ["email","site","cidade","uf","cargo","cnpj_empresa","cidade_de_atuacao","estado_de_atuacao"];
for (const c of campos) {
  if (inc[c] && inc[c].toString().trim() !== "") body[c] = inc[c].toString().trim();
}

// Status: so aceita valor da lista branca, normalizado.
const STATUS_VALIDOS = ["em atendimento","retrabalharnofuturo","naoeoICP","encaminhar parcerias"];
if (inc.status_plano_acao && inc.status_plano_acao.toString().trim() !== "") {
  const bruto = inc.status_plano_acao.toString().trim();
  const match = STATUS_VALIDOS.find(s => s.toLowerCase() === bruto.toLowerCase());
  if (match) body.status_plano_acao = match;
  else throw new Error(`status_plano_acao invalido: "${bruto}". Validos: ${STATUS_VALIDOS.join(", ")}`);
}

// fup: so YYYY-MM-DD.
if (inc.fup && inc.fup.toString().trim() !== "") {
  const fup = inc.fup.toString().trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(fup)) throw new Error(`fup invalido: "${fup}". Formato esperado YYYY-MM-DD.`);
  body.fup = fup;
}
if (body.status_plano_acao === "retrabalharnofuturo" && !body.fup)
  throw new Error("status retrabalharnofuturo exige o campo fup (YYYY-MM-DD).");

// Observacao NOVA que a IA mandou nesta chamada.
const obsNova = (inc.observacao != null ? String(inc.observacao) : "").trim();

// obs obrigatoria nos status terminais: valida a NOVA (a mesclada quase sempre existe).
const EXIGEM_OBS = ["naoeoICP","encaminhar parcerias"];
if (EXIGEM_OBS.includes(body.status_plano_acao) && !obsNova)
  throw new Error(`status ${body.status_plano_acao} exige o campo observacao preenchido.`);

// ===== MESCLA: nunca sobrescreve. Integra a nova nota ao historico. =====
function hoje() {
  const d = new Date();
  const p = (x) => String(x).padStart(2, "0");
  return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`;
}
function norm(s) { return String(s || "").replace(/\s+/g, " ").trim().toLowerCase(); }

if (obsNova) {
  const SEP = "\n\n--- historico ---\n";
  const bloco = `[${hoje()}] ${obsNova}`;

  if (!obsAntiga) {
    // Primeira nota do lead.
    body.observacao = bloco;
  } else if (norm(obsAntiga).includes(norm(obsNova))) {
    // Mesma nota reenviada no mesmo caso: nao duplica, mantem o que ja tem.
    body.observacao = obsAntiga;
  } else {
    // Nota nova no topo, historico anterior preservado abaixo.
    let merged = `${bloco}${SEP}${obsAntiga}`;
    const LIMITE = 4000; // evita crescimento sem fim: corta o rabo do historico
    if (merged.length > LIMITE) merged = merged.slice(0, LIMITE).trim() + "\n[...]";
    body.observacao = merged;
  }
}
// Se a IA NAO mandou observacao nova, o campo nao vai no body -> a API preserva o texto atual.

return { json: { body } };

